"""Headless query and text renderers."""
import csv
import io
import json
import math
import re
import unicodedata
from .database import Json

ANSI=re.compile(r'\x1b(?:\[[0-?]*[ -/]*[@-~]|\][^\x07]*(?:\x07|\x1b\\))')

class Number(str):
    pass


def json_value(v):
    if isinstance(v,Json):
        try:return json.loads(v,parse_float=Number,parse_int=Number)
        except (ValueError,TypeError):return str(v)
    return v


def jdump(value,pretty=False,level=0):
    value=json_value(value)
    if isinstance(value,Number):return str(value)
    if value is None:return 'null'
    if value is True:return 'true'
    if value is False:return 'false'
    if isinstance(value,int):return str(value)
    if isinstance(value,float):
        if not math.isfinite(value):return 'null'
        s=format(value,'.20g')
        if '.' not in s and 'e' not in s.lower():s+='.0'
        return s
    if isinstance(value,bytes):value=value.decode('utf-8','replace')
    if isinstance(value,str):return json.dumps(value,ensure_ascii=False)
    if isinstance(value,(tuple,list)):
        if not value:return '[]' if not pretty else '[\n'+'    '*level+']'
        if not pretty:return '['+','.join(jdump(x) for x in value)+']'
        return '[\n'+',\n'.join('    '*(level+1)+jdump(x,True,level+1) for x in value)+'\n'+'    '*level+']'
    if isinstance(value,dict):
        if not value:return '{}' if not pretty else '{\n'+'    '*level+'}'
        if not pretty:return '{'+','.join(jdump(str(k))+':'+jdump(v) for k,v in value.items())+'}'
        return '{\n'+',\n'.join('    '*(level+1)+jdump(str(k))+': '+jdump(v,True,level+1) for k,v in value.items())+'\n'+'    '*level+'}'
    return jdump(str(value))


def textval(v):
    if v is None:return '<NULL>'
    if isinstance(v,float):
        if math.isnan(v):return '<NULL>'
        s=format(v,'.16g')
        return s
    if isinstance(v,bytes):return v.decode('utf-8','replace')
    return str(v)


def clean_display(s):
    s=ANSI.sub('',s)
    return s.replace('\n','␊').replace('\r','␍').replace('\t',' ').replace('\x00','␀')


def width(s):
    return sum(0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in 'WF' else 1 for c in s)


def pad(s,n,right=False):
    return (' '*(max(0,n-width(s)))+s) if right else (s+' '*max(0,n-width(s)))


def middle(s,n):
    w=width(s)
    l=max(0,(n-w)//2)
    return ' '*l+s+' '*max(0,n-w-l)


def elide(s,n):
    if width(s)<=n:return s
    a=n//2;b=n-a-1
    # Headless tables use a balanced middle ellipsis.
    return s[:a]+'⋯'+(s[-b:] if b>0 else '')


def identifier(name):
    n=name.lower()
    if n.startswith('c_') and n not in ('c_count',):return True
    return bool(re.search(r'(?:^|[_.])(?:id|pid|uid|gid|tid|status|line|port|mark|mode|enabled|visible|cid|pk|notnull|hidden|inode|device|filter_id|selection|top|left|height|inner_height|range_start|range_stop|capture_index|capture_count|match_index|syslog_version)(?:$|[_.])',n) or n.endswith(('_id','_ids','_hash','_code')))


UNITS={'B':1,'KB':1000,'MB':1000**2,'GB':1000**3,'TB':1000**4,'PB':1000**5,
       'KiB':1024,'MiB':1024**2,'GiB':1024**3,'TiB':1024**4,
       'ns':1e-9,'us':1e-6,'µs':1e-6,'ms':1e-3,'s':1,'m':60,'h':3600,'d':86400,'%':.01}

def numeric_string(s):
    if not isinstance(s,str) or isinstance(s,Json) or len(s)>128:return None
    m=re.fullmatch(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)(?: ?([A-Za-z%µ]+))?',s)
    if not m:return None
    try:
        n=float(m[1]);unit=m[2]
        if unit:
            if unit not in UNITS:return None
            n*=UNITS[unit]
        return n if math.isfinite(n) else None
    except ValueError:return None


def column_info(result):
    widths=[];numeric=[];types=[]
    for i,name in enumerate(result.names):
        values=[r[i] for r in result.rows]
        first=next((x for x in values if x is not None),None)
        typ='null' if first is None else 'integer' if isinstance(first,int) else 'number' if isinstance(first,float) else 'string'
        num=not identifier(name) and isinstance(first,(int,float))
        if not identifier(name) and isinstance(first,str) and not isinstance(first,Json):
            num=numeric_string(first) is not None
        w=max([width(clean_display(name))]+[width(clean_display(textval(v))) for v in values])
        if num:w=max(w,10)
        widths.append(w);numeric.append(num);types.append(typ)
    return widths,numeric,types


def converted(name,v):
    if isinstance(v,str) and not isinstance(v,Json) and not identifier(name):
        number=numeric_string(v)
        if number is not None:return number
    return json_value(v)


def result_objects(result):
    return [{n:converted(n,v) for n,v in zip(result.names,r)} for r in result.rows]


def render_csv(result):
    buf=io.StringIO()
    wr=csv.writer(buf,lineterminator='\n')
    wr.writerow(result.names)
    for row in result.rows:wr.writerow([textval(v) for v in row])
    return buf.getvalue()


def render_json(result,lines=False):
    rows=result_objects(result)
    if lines:return ''.join(jdump(r)+'\n' for r in rows)
    if not rows:return '[\n\n]\n'
    return jdump(rows,True)+'\n'


def render_raw(result):
    return ''.join(''.join(textval(x) for x in row)+'\n' for row in result.rows)


def render_table(result,boxed=False,start=0,limit=None):
    if not result.rows and not boxed:return ''
    widths,nums,_=column_info(result)
    if not boxed:widths=[min(x,120) for x in widths]
    def value(v,i):
        s=clean_display(textval(v))
        if not boxed:s=elide(s,widths[i])
        # Typed integers are right-aligned even for identifier columns.
        numeric=nums[i] or isinstance(v,(int,float))
        return pad(s,widths[i],numeric)
    if boxed:
        top='┏'+'┳'.join('━'*w for w in widths)+'┓\n'
        header='┃'+'┃'.join('\x1b[1m'+middle(clean_display(n),w)+'\x1b[0m' for n,w in zip(result.names,widths))+'┃\n'
        separator='┡'+'╇'.join('━'*w for w in widths)+'┩\n'
        bottom='└'+'┴'.join('━'*w for w in widths)+'┘\n'
        return top+header+separator+''.join('│'+'│'.join(value(v,i) for i,v in enumerate(r))+'│\n' for r in result.rows)+bottom
    header=''.join(middle(elide(clean_display(n),w),w)+' ' for n,w in zip(result.names,widths))+'\n'
    rows=result.rows[start:None if limit is None else start+limit]
    return header+''.join(''.join(value(v,i)+' ' for i,v in enumerate(r))+'\n' for r in rows)


def render_json_cols(result):
    widths,nums,types=column_info(result)
    cols=[]
    for i,name in enumerate(result.names):
        values=[r[i] for r in result.rows]
        first=next((v for v in values if v is not None),None)
        parsed=[]
        if isinstance(first,str):
            for v in values:
                try:parsed.append(json.loads(v) if v is not None else None)
                except (ValueError,TypeError):parsed=[];break
        if parsed and isinstance(next((v for v in parsed if v is not None),None),dict):
            keys=[]
            for v in parsed:
                if isinstance(v,dict):
                    for k in v:
                        if k not in keys:keys.append(k)
            for k in keys:
                cols.append({'name':k,'type':'any','values':[v.get(k) if isinstance(v,dict) else None for v in parsed]})
        else:
            cols.append({'name':name,'type':types[i],'width':widths[i],'values':[converted(name,v) for v in values]})
    if not cols:return '[\n    ]\n'
    return '[\n    '+'\n    ,'.join(jdump(c) for c in cols)+'\n    ]\n'
