"""Timestamp and relative-time handling."""
import datetime as dt
import email.utils
import math
import re
import time

UTC=dt.timezone.utc

def now():return dt.datetime.now(UTC)
def stamp(d):return d.astimezone(UTC).strftime('%Y-%m-%d %H:%M:%S.%f')
def epoch_us(d):return int(d.timestamp()*1000000)


def parse_time(value,base=None,numeric='auto'):
    base=base or now()
    if isinstance(base,(float,int)):base=dt.datetime.fromtimestamp(base,UTC)
    if isinstance(value,dt.datetime):return value.replace(tzinfo=value.tzinfo or UTC).astimezone(UTC)
    if isinstance(value,(int,float)):
        v=float(value)
        if numeric=='ms' or (numeric=='auto' and abs(v)>1e11):v/=1000
        if numeric=='us':v=float(value)/1000000
        return dt.datetime.fromtimestamp(v,UTC)
    if value is None:return None
    s=str(value).strip()
    if not s:return None
    if s.lower() in ['now','today','yesterday','tomorrow']:
        if s.lower()=='now':return now()
        d=base.replace(hour=0,minute=0,second=0,microsecond=0)
        return d+dt.timedelta(days={'today':0,'yesterday':-1,'tomorrow':1}[s.lower()])
    if re.fullmatch(r'\d{10}(?:\.\d+)?',s):
        try:return parse_time(float(s),base)
        except:pass
    if re.fullmatch(r'\d{13,16}',s):
        try:return parse_time(int(s),base,'ms' if len(s)<15 else 'us')
        except:pass
    # Common ISO timestamps, including nanosecond fractions and comma fractions.
    iso=s.replace(',','.')
    if re.match(r'^\d{4}/\d\d/\d\d',iso):iso=iso[:10].replace('/','-')+iso[10:]
    iso=re.sub(r'\.(\d{6})\d+',r'.\1',iso)
    if iso.endswith('Z'):iso=iso[:-1]+'+00:00'
    try:
        d=dt.datetime.fromisoformat(iso)
        return d.replace(tzinfo=d.tzinfo or UTC).astimezone(UTC)
    except ValueError:pass
    if re.match(r'^\d\d:\d\d',iso):
        try:
            t=dt.time.fromisoformat(iso)
            d=dt.datetime.combine(base.date(),t)
            return d.replace(tzinfo=d.tzinfo or UTC).astimezone(UTC)
        except ValueError:pass
    pats=['%d/%b/%Y:%H:%M:%S %z','%d/%b/%Y:%H:%M:%S',
          '%b %d %H:%M:%S %Y','%b %d %Y %H:%M:%S',
          '%a %b %d %H:%M:%S.%f %Y','%a %b %d %H:%M:%S %Y',
          '%Y%m%d %H:%M:%S.%f','%Y%m%d %H:%M:%S',
          '%m/%d/%Y %H:%M:%S','%d-%b-%Y %H:%M:%S.%f',
          '%d-%b-%Y %H:%M:%S','%Y-%m-%d %H:%M','%Y-%m-%d']
    for p in pats:
        try:
            d=dt.datetime.strptime(s,p)
            return d.replace(tzinfo=d.tzinfo or UTC).astimezone(UTC)
        except ValueError:pass
    for p in ['%b %d %H:%M:%S.%f','%b %d %H:%M:%S','%m-%d %H:%M:%S.%f','%m-%d %H:%M:%S']:
        try:
            d=dt.datetime.strptime(s,p).replace(year=base.year,tzinfo=UTC)
            return d
        except ValueError:pass
    for p in ['%I:%M%p','%I%p','%H:%M']:
        try:
            t=dt.datetime.strptime(s.upper(),p)
            return base.replace(hour=t.hour,minute=t.minute,second=0,microsecond=0)
        except ValueError:pass
    try:
        d=email.utils.parsedate_to_datetime(s)
        return d.replace(tzinfo=d.tzinfo or UTC).astimezone(UTC)
    except (ValueError,TypeError):pass
    rel=s.lower()
    ago=rel.endswith(' ago')
    rel=re.sub(r'\s+ago$','',rel)
    sec=parse_duration(rel)
    if sec is not None:return base+dt.timedelta(seconds=(-sec if ago else sec))
    return None

DURATION_UNITS={'ns':1e-9,'nanosecond':1e-9,'us':1e-6,'microsecond':1e-6,
                'ms':.001,'millisecond':.001,'s':1,'sec':1,'second':1,
                'm':60,'min':60,'minute':60,'h':3600,'hr':3600,'hour':3600,
                'd':86400,'day':86400,'w':604800,'week':604800,
                'month':2592000,'mon':2592000,'y':31536000,'year':31536000}

def parse_duration(s):
    s=str(s).strip().lower()
    if not s:return None
    if re.fullmatch(r'[+-]?\d+(?:\.\d+)?',s):return float(s)
    ms=list(re.finditer(r'([+-]?\d+(?:\.\d+)?)\s*([a-z]+)',s))
    if not ms or re.sub(r'([+-]?\d+(?:\.\d+)?)\s*([a-z]+)','',s).strip():return None
    total=0
    for m in ms:
        u=m[2]
        if u not in DURATION_UNITS and u.endswith('s'):u=u[:-1]
        if u not in DURATION_UNITS:return None
        total+=float(m[1])*DURATION_UNITS[u]
    return total


def slice_time(value,interval='1m'):
    d=parse_time(value,numeric='ms' if isinstance(value,(int,float)) else 'auto')
    if d is None:raise ValueError('unable to parse time value -- '+str(value))
    s=str(interval)
    if s.startswith(('before ','after ')):
        when=parse_time(s.split(' ',1)[1],d)
        if when is None:raise ValueError('unable to parse slice -- '+s)
        if s.startswith('before '):return stamp(when) if d<when else None
        return stamp(when) if d>=when else None
    period=parse_duration(s)
    if period is None or period<=0:raise ValueError('unable to parse slice -- '+s)
    micros=int(period*1000000)
    n=epoch_us(d)
    return stamp(dt.datetime.fromtimestamp((n-n%micros)/1000000,UTC))
EOF"}

