    if flags:
        try:convert=json.loads(flags).get('convert-numbers',True)
        except ValueError:pass
    names={v:k for k,v in r.groupindex.items()}
    for mi,m in enumerate(r.finditer(as_text(value))):
        if into_json:
            out.append({'match_index':mi,'content':Json(capture_json(r,m,convert)),'value':value,'pattern':pattern,'flags':flags})
        else:
            for ci in range(r.groups+1):
                a,b=m.span(ci)
                out.append({'match_index':mi,'capture_index':ci,'capture_name':names.get(ci),'capture_count':r.groups+1,'range_start':a+1 if a>=0 else 0,'range_stop':b+1 if b>=0 else 0,'content':m.group(ci),'value':value,'pattern':pattern})
    return out


def fstat_rows(params):
    pattern=params.get('pattern')
    if pattern is None:return []
    paths=sorted(glob.glob(pattern)) or [pattern]
    result=[]
    for p in paths:
        row={'st_parent':os.path.dirname(p) or '.','st_name':os.path.basename(p),'pattern':pattern}
        try:
            s=os.lstat(p)
            for k in ['dev','ino','nlink','uid','gid','rdev','size','blksize','blocks']:
