            row['st_mode']=stat.filemode(s.st_mode)
            row['st_type']='dir' if stat.S_ISDIR(s.st_mode) else 'lnk' if stat.S_ISLNK(s.st_mode) else 'reg' if stat.S_ISREG(s.st_mode) else 'other'
            try:row['st_user']=pwd.getpwuid(s.st_uid).pw_name
            except KeyError:row['st_user']=str(s.st_uid)
            try:row['st_group']=grp.getgrgid(s.st_gid).gr_name
            except KeyError:row['st_group']=str(s.st_gid)
            for k in ['atime','mtime','ctime']:row['st_'+k]=stamp(dt.datetime.fromtimestamp(getattr(s,'st_'+k),UTC))
            try:
                if stat.S_ISREG(s.st_mode):
                    with open(p,'rb') as f:row['data']=f.read(32*1024*1024)
            except OSError:pass
        except OSError as e:row['error']=e.strerror
        result.append(row)
    return result
