"""Discovery of fields in loosely structured message bodies."""
import json
import re
from .database import Json


def convert_token(s):
    if s=='true':return True
    if s=='false':return False
    if s=='null':return None
    if re.fullmatch(r'(?:0|[1-9]\d*)',s):
        try:return int(s)
        except ValueError:pass
    if re.fullmatch(r'(?:0|[1-9]\d*)\.\d+',s):
        try:return float(s)
        except ValueError:pass
    if len(s)>=2 and s[0] in '\"\'' and s[-1]==s[0]:
        try:return json.loads(s) if s[0]=='"' else s[1:-1]
        except ValueError:return s[1:-1]
    if s.startswith(('[','{')):
        try:return json.loads(s)
        except ValueError:pass
    return s


def logfmt(s):
    out={}
    for m in re.finditer(r'([^\s=]+)=("(?:\\.|[^"\\])*"|[^\s]*)',str(s)):
        v=m[2]
        if v.startswith('"'):
            try:v=json.loads(v)
            except ValueError:v=v[1:-1]
        elif v in ('true','false'):v=v=='true'
        elif re.fullmatch(r'[+-]?\d+',v):
            try:v=int(v)
            except ValueError:pass
        elif re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?',v):
            try:v=float(v)
            except ValueError:pass
        out[m[1]]=v
    return out

