def fuzzy_match(pattern,text):
    # Subsequence scoring rewards word starts and adjacent matches.
    p=str(pattern).lower();s=str(text).lower();pos=-1;score=100
    for i,c in enumerate(p):
        nxt=s.find(c,pos+1)
        if nxt<0:return None
        if i==0:score-=min(nxt*3,9)
        if nxt==0 or text[nxt-1] in '_ -/.':score+=15
        if nxt==pos+1 and i:score+=15
        score-=max(0,nxt-pos-1)
        pos=nxt
    return score+len(p)*10-(len(s)-len(p))


def yaml_to_json(s):
    # A compact YAML subset sufficient for scalar mappings and lists, without
    # an external YAML runtime dependency.
    try:return Json(json.loads(s))
    except (ValueError,TypeError):pass
    lines=[x for x in str(s).splitlines() if x.strip() and not x.lstrip().startswith('#')]
    def scalar(t):
        t=t.strip()
        if t in ('true','false','null','~'):return {'true':True,'false':False,'null':None,'~':None}[t]
        try:return json.loads(t)
        except ValueError:return t.strip('"\'')
    def block(i,indent):
        obj=[] if lines[i].lstrip().startswith('- ') else {}
        while i<len(lines):
            l=lines[i];n=len(l)-len(l.lstrip())
            if n<indent:break
            if n>indent:i+=1;continue
            t=l.strip()
            if isinstance(obj,list):
                v=t[2:];obj.append(scalar(v));i+=1
            else:
                k,sep,v=t.partition(':')
                if not sep:i+=1;continue
                if v.strip():obj[k.strip()]=scalar(v);i+=1
                elif i+1<len(lines) and len(lines[i+1])-len(lines[i+1].lstrip())>indent:
                    val,i=block(i+1,len(lines[i+1])-len(lines[i+1].lstrip()));obj[k.strip()]=val
                else:obj[k.strip()]=None;i+=1
        return obj,i
    return Json(block(0,len(lines[0])-len(lines[0].lstrip()))[0] if lines else None)


