        for n,v in fmt.get('value',{}).items():
            typ={'integer':'INTEGER','float':'REAL','double':'REAL','boolean':'BOOLEAN'}.get(v.get('kind'),'TEXT')
            insert.append([n,typ,0,0])
        cols[3:3]=insert
        self.custom_tables[name]=cols
        self.db.table(name,cols,lambda p,name=name:[r for r in self.visible if r['_format']==name],lambda o,n,r:self.update_log(o,n,r))

    def series_rows(self,params):
        start=int(params.get('start',0) or 0);stop=int(params.get('stop',0xffffffff) or 0);step=int(params.get('step',1) or 1)
        if start>stop:return []
        values=list(range(start,min(stop,start+abs(step)*1000000)+1,abs(step)))
        if step<0:values.reverse()
        return [{'value':x,'start':start,'stop':stop,'step':abs(step)} for x in values]

    def make_logline(self,name='logline',permanent=False):
        focused=self.focused()
        fmt=focused['_format'] if focused else 'generic_log'
        cols=copy.deepcopy(self.custom_tables.get(fmt,INTERFACES.get(fmt,INTERFACES['generic_log'])))
        vals=None;template=None
        if focused and focused['_body'] is not None:
            template,vals=discover(focused['_body'])
        if vals:
            insert_at=next((i for i,c in enumerate(cols) if c[0]=='log_part'),3)
            fields=[]
            for k,v in vals.items():
                if any(c[0]==k for c in cols):continue
                typ='FLOAT' if isinstance(v,(int,float)) and not isinstance(v,bool) else 'TEXT'
                fields.append([k,typ,0,0])
            cols[insert_at:insert_at]=fields
        def rows(params):
            out=[]
            for r in self.visible:
                if r['_format']!=fmt:continue
                rt,rv=discover(r['_body']) if r['_body'] is not None else (None,None)
                if focused and template is not None and rt!=template:continue
                d=dict(r)
                for k,v in (rv or {}).items():
                    if isinstance(v,(dict,list)):v=Json(v)
                    elif isinstance(v,(int,float)) and not isinstance(v,bool):v=float(v)
                    d[k]=v
                out.append(d)
            return out
        self.db.table(name,cols,rows,lambda old,new,row:self.update_log(old,new,row))
        if permanent:self.dynamic_tables[name]=(fmt,template)

    def table_rows(self,name,params):
        if name in ('regexp_capture','regexp_capture_into_json'):return regex_rows(params,name.endswith('into_json'))
        if name=='fstat':return fstat_rows(params)
        if name=='environ':return [{'name':k,'value':v,'_rowid':i} for i,(k,v) in enumerate(os.environ.items())]
        if name=='lnav_file':
            out=[]
            for i,f in enumerate(self.files):
                st=f.stat
                out.append({'device':st.st_dev if st else 0,'inode':st.st_ino if st else 0,'filepath':f.path,
                            'mimetype':f.mimetype,'content_id':f.content_id,'format':f.format,
                            'lines':sum(len(r['_lines']) for r in f.records) if f.format else len(f.lines),
                            'time_offset':f.offset,'options_path':None,'options':None,'content':f.content,'_rowid':i})
            return out
        if name=='lnav_view_files':return [{'view_name':'log' if f.format else 'text','filepath':f.path,'visible':int(not f.hidden),'_rowid':i} for i,f in enumerate(self.files)]
        if name=='lnav_view_stack':return [{'name':n,'_rowid':i} for i,n in enumerate(self.stack)]
        if name=='lnav_view_filters':return [{'view_name':f.view,'filter_id':f.id,'enabled':int(f.enabled),'type':f.type,'language':f.language,'pattern':f.pattern,'_rowid':f.id} for f in self.filters]
        if name=='lnav_view_filter_stats':return [{'view_name':f.view,'filter_id':f.id,'hits':f.hits} for f in self.filters]
        if name in ('lnav_views','lnav_views_echo'):
            rows=[]
            for i,n in enumerate(VIEW_NAMES):
                top=self.tops[n];height=24 if n==self.view else 1
                length=0;time=None;file=None;meta=None
                if n=='log':
                    length=len(self.log_lines);r=self.focused()
                    if r:time=r['log_time'];file=r['log_path'];meta=self.top_meta(r)
                elif n=='text':
                    lines=self.text_lines();length=len(lines)
                    if lines:file=lines[0][0].path
                elif n=='db':
                    length=len(self.last_result.rows)+1 if self.last_result else 0
                    if length:meta={'breadcrumbs':[]}
                elif n=='help':length=len(self.helptext.splitlines())
                elif n=='schema':length=len(self.schema_text.splitlines())
                options={'row-details':'hide'}
                if n in ('log','text'):options['row-time-offset']='hide'
                options['hidden-fields']='hide';options['word-wrap']='normal' if self.wrap[n] else 'none'
                rows.append({'name':n,'top':top,'left':0,'height':height,'inner_height':length,'top_time':time,'top_file':file,'paused':0,'search':self.searches[n],
                             'filtering':int(self.filtering) if n in ('log','text') else 0,'movement':'top','top_meta':Json(meta) if meta is not None else None,
                             'selection':top,'options':Json(options),'selected_text':None,'row_details':None,'_rowid':i})
            return rows
        if name=='lnav_log_breakpoints':return self.breakpoints
        if name=='all_logs':return self.visible
        if name in self.search_tables:return self.search_rows(name)
        return [r for r in self.visible if r['_format']==name]

    def top_meta(self,r):
        f=r['_file']
        times=['-1 day','-1h','-30m','-15m','-5m','-1m','+1m','+5m','+15m','+30m','+1h','+1 day']
        fmts=sorted(set(x['_format'] for x in self.visible))
        names=sorted(set(x['_file'].name for x in self.visible))
        crumbs=[{'display_value':r['log_time'].replace(' ','T'),'search_placeholder':'(Enter an absolute or relative time)','possibilities':[{'display_value':x} for x in times]},
                {'display_value':r['_format'],'search_placeholder':'','possibilities':[{'display_value':x} for x in fmts]},
                {'display_value':f.name+'['+str(r['_id'][1])+']','search_placeholder':'','possibilities':[{'display_value':x} for x in names]}]
        if r['_format']=='syslog_log':
            for k in ['log_pid','log_syslog_tag']:
                vals=sorted(set(str(x[k]) for x in self.visible if x.get(k) is not None))
                if r.get(k) is not None:
                    text=str(r[k]).rjust(6) if k=='log_pid' else str(r[k])
                    crumbs.append({'display_value':text,'search_placeholder':'','possibilities':[{'display_value':x} for x in vals]})
        return {'time':r['log_time'],'file':f.path,'anchor':r['log_line_link'],'breadcrumbs':crumbs}

    def update_log(self,old,new,row):
        if old is None:return
        rec=next((r for r in self.visible if r['log_line']==old),None)
        if rec is None or row is None:return
        for k in ['log_mark','log_sticky_mark','log_comment','log_tags','log_annotations','log_user_opid']:
            if k in row:
                val=row[k]
                if k in ('log_tags','log_annotations') and val is not None:val=Json(val)
                rec[k]=val
        if row.get('log_part')!=rec.get('log_part'):rec['_partition']=row.get('log_part') or ''
        self.changed=True

    def update_table(self,name,old,new,row):
        if name=='environ':
            if row is not None:os.environ[str(row['name'])]='' if row.get('value') is None else str(row['value'])
            return new or 0
        if name=='lnav_views' and row:
            n=row.get('name')
            if n in self.tops:
                if row.get('top') is not None:self.tops[n]=max(0,int(row['top']))
                self.searches[n]=row.get('search') or ''
                if n in ('log','text'):self.filtering=bool(row.get('filtering',1))
                if row.get('options'):
                    try:self.wrap[n]=json.loads(row['options']).get('word-wrap','none')!='none'
                    except ValueError:pass
                self.changed=True
            return old
        if name=='lnav_view_filters':
            if old is not None:
                found=next((x for x in self.filters if x.id==old),None)
                if found:
                    if row is None:self.filters.remove(found)
                    else:
                        found.enabled=bool(row['enabled']);found.pattern=row['pattern'];found.type=row['type']
                        found.regex=Regex(found.pattern,True)
            elif row:
                self.add_filter(row['pattern'],row['type'],row.get('view_name','log'))
            self.changed=True;return new or len(self.filters)
        if name in ('lnav_file','lnav_view_files') and row and old is not None:
            f=self.files[int(old)]
            if name=='lnav_file':
                offset=row.get('time_offset')
                if offset is not None:f.offset=int(offset)
            else:f.hidden=not row.get('visible',1)
            self.changed=True;return old
        if name=='lnav_view_stack':
            if row is None and old is not None:
                if self.stack:self.stack.pop();self.view=self.stack[-1] if self.stack else 'log'
            elif row:
                self.view=row['name'];self.stack.append(self.view)
            return len(self.stack)-1
        return self.update_log(old,new,row)

    def output(self,text,path='-',append=False):
        if path=='-' and self.redirect:path=self.redirect
        if path=='-':
            sys.stdout.write(text);sys.stdout.flush();self.printed=True
        else:
            try:
                with open(os.path.expanduser(self.expand(path)),'a' if append else 'w',encoding='utf-8') as f:f.write(text)
            except OSError as e:raise CommandError('cannot open file: '+path,e.strerror)

    def snippet(self,command=None):
        command=self.current if command is None else command
        lines=command.splitlines() or ['']
        return ' --> '+self.source+':'+str(self.line)+'\n'+''.join(' | '+x.ljust(40)+'\n' for x in lines)

    def error(self,message,reason=None,helptext=None,command_help=False,command=None,context=True):
        self.had_error=True
        out='  error: '+message+'\n'
        if reason:out+=' reason: '+reason+'\n'
        if context:out+=self.snippet(command)
        name=self.current.lstrip(':').split(' ',1)[0]
        if helptext:out+=' = help: '+helptext+'\n'
        elif command_help and name in COMMAND_HELP:
            usage,desc=COMMAND_HELP[name]
            out+=' = help: :'+name+usage+'\n         '+'═'*70+'\n'
            for s in desc.splitlines():out+='         '+s+'\n'
        sys.stderr.write(out)

    def expand(self,text):
        def sub(m):
            key=m[1] or m[2]
            return str(self.variables.get(key,os.environ.get(key,'')))
        text=re.sub(r'\$\{([^}]+)\}|\$([A-Za-z_][\w]*|\d+)',sub,str(text))
        return text

    def execute_sql(self,sql):
        if sql.startswith('.schema'):
            self.schema_text=self.schema();self.switch('schema');return
        if sql.startswith('.read '):
            path=self.expand(sql[6:].strip())
            try:sql=Path(path).read_text()
            except OSError as e:raise CommandError('unable to read script file: '+path+' -- '+e.strerror)
        elif sql.startswith('.dump'):
            self.schema_text=self.schema();self.switch('schema');return
        elif sql.startswith('.save '):
            # Save a snapshot of query results as an ordinary SQLite database.
            name=self.expand(sql[6:].strip())
            if self.last_result:
                conn=sqlite3.connect(name)
                conn.execute('CREATE TABLE IF NOT EXISTS results('+','.join('"'+n.replace('"','""')+'"' for n in self.last_result.names)+')')
                conn.executemany('INSERT INTO results VALUES('+','.join('?' for _ in self.last_result.names)+')',self.last_result.rows)
                conn.commit();conn.close()
            return
        if sql.lstrip().startswith(('from ','let ')):
            sql=self.prql(sql)
        self.make_logline()
        self.last_result=None
        bindings=dict(os.environ);bindings.update(self.variables)
        try:
            res=self.db.execute(sql,bindings)
            if res is not None:
                self.last_result=res;self.tops['db']=0
                if res.rows:self.switch('db')
            if self.changed:self.refresh()
        except SQLError as e:
            err=self.db.last_error
            if e.stage=='compile':self.error('failed to compile SQL statement',str(e),command=sql)
            elif isinstance(err,FunctionError):
                self.last_result=getattr(e,'result',None)
                self.error(err.title or 'call to '+err.signature+' failed',err.reason,err.helptext)
            else:
                self.last_result=getattr(e,'result',None)
                self.error('failed to execute SQL statement',str(err or e))

    def schema(self):
        out="ATTACH DATABASE '' AS 'main';\nATTACH DATABASE '' AS 'lnav_db';\n"
        r=self.db.execute("SELECT sql FROM lnav_db.sqlite_master WHERE sql IS NOT NULL ORDER BY rowid")
        if r:out+=''.join(str(row[0])+';\n' for row in r.rows)
        return out

    def prql(self,sql):
        parts=re.split(r'\s*\|\s*|\n',sql.strip());table='all_logs';select='*';where=[];order='';limit=''
        for part in parts:
            part=part.strip()
            if part.startswith('from '):table=part[5:].strip().replace('logs.','')
            elif part.startswith('filter '):where.append(part[7:].replace('==','=').replace('&&',' AND ').replace('||',' OR '))
            elif part.startswith('select '):select=part[7:].strip('{} ')
            elif part.startswith('take '):limit=' LIMIT '+part[5:].strip()
            elif part.startswith('sort '):
                fields=part[5:].strip('{} ');order=' ORDER BY '+','.join(x[1:]+' DESC' if x.strip().startswith('-') else x for x in fields.split(','))
            elif part.startswith('aggregate '):
                fields=part[10:].strip('{} ');select=re.sub(r'\bcount\s+this\b','count(*)',fields)
                select=re.sub(r'(\w+)\s*=\s*([^,]+)',r'\2 AS \1',select)
        return 'SELECT '+select+' FROM '+table+(' WHERE '+' AND '.join(where) if where else '')+order+limit

    def switch(self,view,toggle=False):
        aliases={'sql':'db','spectrogram':'spectro','hist':'histogram'}
        view=aliases.get(view,view)
        if view not in VIEW_NAMES:raise CommandError('invalid view name -- '+view)
        if toggle and self.view==view:
            if len(self.stack)>1:self.stack.pop();self.view=self.stack[-1]
            else:self.view='log';self.stack=['log']
        else:
            self.view=view
            if not self.stack or self.stack[-1]!=view:self.stack.append(view)

    def view_length(self):
        if self.view=='log':return len(self.log_lines)
        if self.view=='text':return len(self.text_lines())
        if self.view=='db':return len(self.last_result.rows)+1 if self.last_result else 0
        if self.view=='help':return len(self.helptext.splitlines())
        if self.view=='schema':return len(self.schema_text.splitlines())
        return 0

    def goto(self,arg,relative=False):
        s=arg.strip();length=self.view_length()
        if not s:return
        val=None
        if re.fullmatch(r'[+-]?\d+',s):
            val=int(s)
            if relative:val+=self.tops[self.view]
            elif val<0:val=length+val
        elif re.fullmatch(r'[+-]?\d+(?:\.\d+)?%',s):
            val=int(float(s[:-1])*length/100)
            if relative:val+=self.tops[self.view]
        elif s.startswith('#msg'):
            val=next((r['log_line'] for r in self.visible if r['log_line_link']==s),None)
        else:
            base=parse_time(self.focused()['log_time']) if self.focused() else now()
            target=parse_time(s,base)
            if target:
                val=next((r['log_line'] for r in self.visible if parse_time(r['log_time'])>=target),max(0,length-1))
        if val is None:raise CommandError('invalid argument: '+s,'expecting line number/percentage, timestamp, or relative time')
        self.tops[self.view]=min(max(0,length-1),max(0,val))

    def add_filter(self,pattern,typ,view=None):
        view=view or self.view
        if not pattern:raise CommandError('expecting a regular expression to filter')
        regex=Regex(pattern,True)
        existing=next((f for f in self.filters if f.pattern==pattern and f.view==view),None)
        if existing:existing.enabled=True;existing.type=typ;existing.regex=regex
        else:self.filters.append(Filter(max([x.id for x in self.filters]+[0])+1,pattern,typ,view,True,'regex',regex))
        self.refresh()

    def filtered_message_rows(self,marked=True):
        return [r for r in self.visible if not marked or r.get('log_mark')]

    def view_text(self,whole=False,raw=False):
        top=0 if whole else self.tops[self.view]
        if self.view=='log':
            lines=self.log_lines[top:]
            if raw:
                recs=[]
                for r,i,s in lines:
                    if not recs or recs[-1] is not r:recs.append(r)
                return ''.join(r['_raw']+'\n' for r in recs)
            return ''.join(self.clean_logline(s)+'\n' for r,i,s in lines)
        if self.view=='text':return ''.join(self.clean_logline(s)+'\n' for f,i,s in self.text_lines()[top:])
        if self.view=='db':
            return render.render_table(self.last_result,start=max(0,top-1)) if self.last_result else ''
        text=self.helptext if self.view=='help' else self.schema_text if self.view=='schema' else self.pretty_text
        return ''.join(x+'\n' for x in text.splitlines()[top:])

    def clean_logline(self,line):
        s=render.ANSI.sub('',line).rstrip('\r')
        s=s.expandtabs(8)
        return s if s else ' '

    def log_jsonlines(self,all_lines=False):
        rows=self.filtered_message_rows(not all_lines);out=[]
        for r in rows:
            pairs=[('log_path',r['log_path']),('log_time',r['log_time'].replace(' ','T')),('log_level',r['log_level']),('log_line_link',r['log_line_link'])]
            if r['_format']=='generic_log':
                match=None
                for expr in (GENERIC1,GENERIC2,GENERIC11):
                    match=expr.match(r['_raw'])
                    if match:break
                if match:pairs += [('log_time',match[1]),('log_level',match[2])]
            elif r['_regex']=='structured':
                try:
                    obj=json.loads(r['_raw'])
                    pairs+=list(obj.items())
                except ValueError:pass
            else:
                cols=INTERFACES.get(r['_format'],[])
                for n,t,h,p in cols:
                    if n in ['log_line','log_time','log_level','log_part','log_idle_msecs','log_mark','log_comment','log_tags','log_annotations','log_filters'] or h:continue
                    if r.get(n) is not None:pairs.append((n,r[n]))
            out.append('{'+','.join(render.jdump(k)+':'+render.jdump(v) for k,v in pairs)+'}\n')
        return ''.join(out)

    def write(self,name,arg):
        opts=shlex.split(self.expand(arg))
        anonymize='--anonymize' in opts;all_lines='--all' in opts
        if '--view' in opts:
            i=opts.index('--view')
            if i+1<len(opts):
                n=opts[i+1]
                if n not in VIEW_NAMES:raise CommandError('invalid view name: '+('' if n=='-' else n))
                self.switch(n);del opts[i:i+2]
        opts=[x for x in opts if not x.startswith('--')]
        if not opts:raise CommandError("expecting file name or '-' to write to the terminal")
        path=opts[-1];res=self.last_result
        if name in ('write-csv-to','write-json-to','write-json-cols-to','write-table-to'):
            if res is None:raise CommandError("no query result to write, use ';' to execute a query")
            fn={'write-csv-to':render.render_csv,'write-json-to':render.render_json,'write-json-cols-to':render.render_json_cols,'write-table-to':lambda r:render.render_table(r,True)}[name]
            text=fn(res)
        elif name=='write-jsonlines-to':
            if self.view=='db' and res is not None:text=render.render_json(res,True)
            else:
                if not all_lines and not self.filtered_message_rows():raise CommandError("no lines marked to write, use 'm' to mark lines")
                text=self.log_jsonlines(all_lines)
        elif name in ('write-view-to','write-screen-to'):text=self.view_text(whole=name=='write-view-to')
        elif name=='write-raw-to' and self.view=='db' and res is not None:text=render.render_raw(res)
        elif name=='write-debug-log-to':text=''
        else:
            if self.view=='log':
                rows=self.filtered_message_rows()
                if not rows:raise CommandError("no lines marked to write, use 'm' to mark lines")
                if name=='write-raw-to':text=''.join(r['_raw']+'\n' for r in rows)
                else:text=''.join(self.clean_logline(s)+'\n' for r in rows for s in r['_lines'])
            elif self.view=='text':
                rows=[(f,i,s) for f,i,s in self.text_lines() if (f.path,i) in self.text_marks]
                if not rows:raise CommandError("no lines marked to write, use 'm' to mark lines")
                text=''.join(self.clean_logline(s)+'\n' for f,i,s in rows)
            elif self.view=='db' and res is not None:text=render.render_table(res)
            else:raise CommandError("no lines marked to write, use 'm' to mark lines")
        if anonymize:text=self.anonymize(text)
        self.output(text,path,append=name=='append-to')

    def shell_command(self,cmd):
        p=subprocess.run(cmd,shell=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        path='shell: '+cmd
        self.add_data(path,p.stdout)
        self.refresh()
        if self.visible:self.switch('log')
        elif self.plain_files:self.text_index=len(self.plain_files)-1;self.switch('text')

    def execute(self,command,source='command-option',line=1):
        self.current=command;self.source=source;self.line=line
        if not command:return
        try:
            prefix=command[0]
            if prefix==';':self.execute_sql(command[1:]);return
            if prefix=='|':self.script(command[1:]);return
            if prefix=='/':
                self.searches[self.view]=command[1:]
                return
            if prefix!=':':raise CommandError('invalid command')
            raw=command[1:].lstrip();name,sep,arg=raw.partition(' ');arg=arg.strip()
            if name not in COMMAND_HELP:
                self.error('unknown command: “'+name+'”',context=False);return
            self.command(name,arg)
        except RegexError as e:
            pattern=arg
            self.had_error=True
            reason=str(e)
            s='  error: “'+pattern+'” is not a valid regular expression\n reason: '+reason+'\n --> pattern\n'
            w=max(40,len(pattern),e.offset+len(reason)+2)
            s+=' | '+pattern.ljust(w)+'\n | '+(' '*e.offset+'^ '+reason).ljust(w)+'\n'
            if name in COMMAND_HELP:
                usage,desc=COMMAND_HELP[name]
                s+=' = help: :'+name+usage+'\n         '+'═'*70+'\n'+''.join('         '+x+'\n' for x in desc.splitlines())
            sys.stderr.write(s)
        except CommandError as e:self.error(str(e),e.reason,e.helptext,e.command_help)
        except (ValueError,OSError,TypeError) as e:self.error(str(e),command_help=True)

    def command(self,name,arg):
        if name.startswith('write-') or name=='append-to':self.write(name,arg);return
        if name=='echo':
            newline=True
            if arg=='-n':arg='';newline=False
            elif arg.startswith('-n '):arg=arg[3:];newline=False
            text=self.expand(arg)
            text=re.sub(r'\\(.)',r'\1',text)
            self.output(text+('\n' if newline else ''));return
        if name in ('filter-in','filter-out'):self.add_filter(arg,'in' if name=='filter-in' else 'out');return
        if name in ('disable-filter','enable-filter','delete-filter'):
            f=next((x for x in self.filters if x.pattern==arg and x.view==self.view),None)
            if f is None:raise CommandError('no such filter -- '+arg)
