    def create_search_table(self,name,pattern):
        reg=Regex(pattern)
        cols=copy.deepcopy(INTERFACES['generic_log'])
        names={v:k for k,v in reg.groupindex.items()}
        fields=[[names.get(i,'col_'+str(i-1)),'TEXT',0,0] for i in range(1,reg.groups+1)]
        cols[3:3]=fields
        self.search_tables[name]=(reg,fields)
        self.db.table(name,cols,lambda p:self.search_rows(name))

    def search_rows(self,name):
        reg,fields=self.search_tables[name];out=[]
        for r in self.visible:
            for m in reg.finditer(r['_display']):
                d=dict(r)
                for i,(n,*_) in enumerate(fields,1):d[n]=m.group(i)
