            try:text=Path(path).read_text()
            except OSError:raise CommandError('unknown script -- '+path+' -- file not found',command_help=False)
        saved=(self.current,self.source,self.line)
        active=None;start=1
        for number,line in enumerate(text.splitlines(),1):
            if not line.strip() or line.lstrip().startswith('#'):continue
            if line.startswith((':',';','|','/')):
                if active is not None:self.execute(active,path,start)
                active=line;start=number
            elif active is not None:active+='\n'+line
        if active is not None:self.execute(active,path,start)
        self.current,self.source,self.line=saved

    def anonymize(self,text):
        def replacement(m):
            key=m[0]
            if key not in self.anonymized:
                n=len(self.anonymized)+1
                self.anonymized[key]=f'10.0.0.{n}' if re.match(r'\d',key) else f'example{n}.com'
            return self.anonymized[key]
        return re.sub(r'\b(?:\d{1,3}\.){3}\d{1,3}\b|\b[\w.-]+@[\w.-]+\.[A-Za-z]+\b',replacement,text)

    def finish(self):
        if not self.options.quiet and not self.printed and not self.had_error:
            sys.stdout.write(self.view_text())
        return 0
