"""Command line entry point and management operations."""
import dataclasses
import json
import os
from pathlib import Path
import re
import shutil
import sys
from .app import App,CommandError,DEFAULTS,BASE
from .timeutil import parse_time
from .render import jdump

VERSION='lnav 0.14.0-8ad2d43'

@dataclasses.dataclass
class Options:
    headless:bool=False
    no_default:bool=False
    quiet:bool=False
    recursive:bool=False
    rotated:bool=False
    timestamps:bool=False
    check:bool=False
    install:bool=False
    management:bool=False
    help:bool=False
    internal_help:bool=False
    version:bool=False
    update:bool=False
    warnings:bool=False
    debug:str=None
    since:object=None
    until:object=None
    includes:list=dataclasses.field(default_factory=list)
    commands:list=dataclasses.field(default_factory=list)
    shells:list=dataclasses.field(default_factory=list)
    paths:list=dataclasses.field(default_factory=list)
    script_stdin:str=''

class ArgumentError(Exception):
    def __init__(self,reason,code=109,text=None):
        self.reason,self.code,self.text=reason,code,text


def help_text(argv0):
    return f'''usage: {argv0} [options] [logfile1 logfile2 ...]

A log file viewer for the terminal that indexes log messages to
make it easier to navigate through files quickly.

Key Bindings
  ?    View/leave the online help text.
  q    Quit the program.

Options
  -h         Print this message, then exit.
  -H         Display the internal help text.

  -I dir     An additional configuration directory.
  -W         Print warnings related to lnav's configuration.
  -u         Update formats installed from git repositories.
  -d file    Write debug messages to the given file.
  -V         Print version information.

  -S,--since Only index log content since this time.
  -U,--until Only index log content until this time.
  -r         Recursively load files from the given directory hierarchies.
  -R         Load older rotated log files as well.
  -c cmd     Execute a command after the files have been loaded.
  -f file    Execute the commands in the given file.
  -e cmd     Execute a shell command-line.
  -t         Treat data piped into standard in as a log file.
  -n         Run without the curses UI. (headless mode)
  -N         Do not open the default syslog file if no files are given.
  -q         Do not print informational messages.

Optional arguments
  logfileN   The log files, directories, or remote paths to view.
             If a directory is given, all of the files in the
             directory will be loaded.

Management-Mode Options
  -i         Install the given format files and exit.  Pass 'extra'
             to install the default set of third-party formats.
  -m         Switch to the management command-line mode.  This mode
             is used to work with lnav's configuration.

Examples
 • To load and follow the syslog file:
     $ lnav                                  

 • To load all of the files in /var/log:
     $ lnav /var/log                         

 • To watch the output of make:
     $ lnav -e 'make -j4'                    

Paths
 • This binary:
    🧭 {os.path.realpath(argv0)}
 • Format files are read from:
    📂 /etc/lnav
    📂 /usr/etc/lnav
 • Configuration, session, and format files are stored in:
    📂 {Path.home() / '.lnav'}

 • Local copies of remote files, files extracted from
   archives, execution output, and so on are stored in:
    📂 /tmp/lnav-user-{os.getuid()}-work

Documentation: https://docs.lnav.org
Contact
  💬 https://github.com/tstack/lnav/discussions
  📫 lnav@googlegroups.com
Version: {VERSION}
'''


def parse_args(args):
    o=Options();i=0;end=False
    simple={'n':'headless','N':'no_default','q':'quiet','r':'recursive','R':'rotated',
            't':'timestamps','C':'check','i':'install','m':'management','h':'help',
            'H':'internal_help','V':'version','u':'update','W':'warnings'}
    longs={'help':'h','version':'V','since':'S','until':'U'}
    while i<len(args):
        a=args[i];i+=1
        if end or not a.startswith('-') or a=='-':o.paths.append(a);continue
        if a=='--':end=True;continue
        if a.startswith('--'):
            name,eq,value=a[2:].partition('=')
            if name not in longs:raise ArgumentError('The following argument was not expected: '+a)
            flag=longs[name];group=flag
            attached=value if eq else None
        else:group=a[1:];attached=None
        pos=0
        while pos<len(group):
            flag=group[pos];pos+=1
            if flag in simple:setattr(o,simple[flag],True);continue
            if flag not in 'IcfdSUe':raise ArgumentError('The following argument was not expected: -'+flag)
            if attached is not None:value=attached;attached=None
            elif pos<len(group):value=group[pos:];pos=len(group)
            else:
                if i>=len(args):raise ArgumentError('-'+flag+': 1 required  missing',114)
                value=args[i];i+=1
            if flag=='I':
                if not os.path.isdir(value):raise ArgumentError('-I: Directory does not exist: '+value,105)
                o.includes.append(value)
            elif flag=='c':
                if not value:raise ArgumentError('-c: empty commands are not allowed',105)
                if value[0] not in ':;|/':
                    text='  error: invalid value for “-c” option\n --> command-line argument\n | '+(' -c '+value).ljust(40)+'\n | '+('    ^ command type prefix is missing').ljust(40)+'\n = help: command arguments must start with one of the following symbols to denote the type of command:\n            : - an lnav command   (e.g. :goto 42)\n            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n            | - an lnav script    (e.g. |rename-stdin foo)\n'
                    raise ArgumentError('',105,text)
                o.commands.append(value)
            elif flag=='f':o.commands.append('|'+value)
            elif flag=='d':o.debug=value
            elif flag=='e':o.shells.append(value)
            elif flag=='S':o.since=value
            elif flag=='U':o.until=value
    if o.install and not o.paths:raise ArgumentError('-i requires file',107)
    return o


def management(o):
    args=o.paths
    def err(message,extra='',code=1):
        sys.stderr.write('  error: '+message+'\n'+extra);return code
    roothelp=' = help: the available operations are:\n          • apps: manage lnav apps\n          • config: perform operations on the lnav configuration\n          • format: perform operations on log file formats\n          • piper: perform operations on piper storage\n          • regex101: create and edit log message regular expressions using regex101.com\n          • crash: manage crash logs\n'
    if not args:return err('expecting an operation to perform',roothelp)
    if args[0] not in ('apps','config','format','piper','regex101','crash'):
        return err('invalid command-line arguments',' reason: The following argument was not expected: '+args[0]+'\n',109)
    if args[0]=='config':
        if len(args)==1:return err('expecting an operation related to lnav configuration',' = help: the available operations are:\n          • get: print the current configuration\n          • blame: print the configuration options and their source\n          • file-options: print the options applied to specific files\n')
        if args[1] in ('get','blame'):
            if len(args)>2:return err('invalid command-line arguments',' reason: The following argument was not expected: '+args[-1]+'\n',109)
            sys.stdout.write(json.dumps(DEFAULTS,ensure_ascii=False,indent=4)+'\n');return 0
        if args[1]=='file-options':
            if len(args)<3:return err('Expecting a file path to check for options')
            sys.stdout.write('{}\n');return 0
    if args[0]=='format':
        if len(args)<2:return err('expecting a format name to operate on')
        from .app import INTERFACES
        name=args[1]
        if name not in INTERFACES:return err('unknown format: '+name)
        if len(args)==2:return err('expecting an operation related to the '+name+' format')
        if args[2]=='test':return 0
    if args[0]=='piper':
        if len(args)==1:return err('expecting an operation related to piper storage',' = help: the available operations are:\n          • list: print the available piper captures\n          • clean: remove all piper captures\n')
        if args[1] in ('list','clean'):return 0
    if args[0]=='crash':
        return err('expecting an operation related to crash logs',' = help: the available operations are:\n          • upload: upload crash logs\n')
    return err('invalid command-line arguments',' reason: The following argument was not expected: '+args[-1]+'\n',109)


def install(o):
    dest=Path.home()/'.lnav'/'formats'/'installed'
    manifest=Path.home()/'.lnav'/'reimplementation-installed.json'
    files=[]
    if manifest.exists():
        try:files=json.loads(manifest.read_text())
        except ValueError:pass
    for src in o.paths:
        try:text=Path(src).read_text()
        except OSError as e:
            sys.stderr.write('  error: unable to open configuration file: '+src+'\n reason: '+e.strerror+'\n');return 1
        try:json.loads(text)
        except ValueError:
            sys.stderr.write('  error: unable to parse configuration file: '+src+'\n');return 1
        dest.mkdir(parents=True,exist_ok=True)
        path=dest/Path(src).name
        path.write_text(text)
        if str(path) not in files:files.append(str(path))
    manifest.write_text(json.dumps(files))
    return 0


def main(argv=None):
    argv=sys.argv if argv is None else argv
    try:o=parse_args(argv[1:])
    except ArgumentError as e:
        sys.stderr.write(e.text or '  error: invalid command-line arguments\n reason: '+e.reason+'\n');return e.code
    if o.version:sys.stdout.write(VERSION+'\n');return 0
    if o.help:sys.stderr.write(help_text(argv[0]));return 0
    if o.management:return management(o)
    if o.install:return install(o)
    if o.update:return 0
    for name in ['since','until']:
        value=getattr(o,name)
        if value is not None:
            parsed=parse_time(value)
            if parsed is None:
                sys.stderr.write('  error: invalid \''+name+'\' time “'+str(value)+'”\n reason: Unrecognized input\n');return 1
            setattr(o,name,parsed)
    if not o.headless and not o.check and not sys.stdout.isatty():
        sys.stderr.write("  error: unable to display interactive text UI\n reason: stdout is not a TTY\n = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n");return 1
    data=b''
    if not sys.stdin.isatty():
        try:data=sys.stdin.buffer.read()
        except OSError:pass
    if '|-' in o.commands:o.script_stdin=data.decode('utf-8','replace');data=b''
    app=App(o)
    try:app.load(o.paths,data)
    except OSError as e:
        sys.stderr.write('  error: unable to open file: '+str(e.filename or '')+'\n reason: '+str(e.strerror)+'\n');return 1
    if o.debug:
        try:Path(o.debug).write_text('lnav: '+VERSION+'\n')
        except OSError:pass
    if o.check:
        failed=False
        for f in app.files:
            if f.format is None and f.path!='stdin':
                sys.stderr.write('error:'+f.path+':no format found for file\n');failed=True
        return int(failed)
    if o.internal_help:app.switch('help')
    for i,c in enumerate(o.commands,1):
        app.execute(c,'command-option',i)
        if app.quit:break
    if not o.headless:
        from .terminal import run
        return run(app)
    return app.finish()
